import bisect

class SkiplistBrute:
    def __init__(self):
        self.nums = []

    def search(self, target):
        idx = bisect.bisect_left(self.nums, target)
        return idx < len(self.nums) and self.nums[idx] == target

    def add(self, num):
        bisect.insort(self.nums, num)              # O(n) shift for insertion

    def erase(self, num):
        idx = bisect.bisect_left(self.nums, num)
        if idx < len(self.nums) and self.nums[idx] == num:
            self.nums.pop(idx)                       # O(n) shift for removal
            return True
        return False

